// Generated by QualityPilot — test case dc558fe1-2cd6-4ce0-a20b-90e9c5b6ea78
// Regression: 'Users' card is missing from the dashboard
import { test, expect } from '../tests/fixtures/base';
import { AUTH_FILE } from '../tests/utils/auth';

test.describe('Regression', () => {
  test.use({ storageState: AUTH_FILE });

  test('Users card is missing from the dashboard', async ({ shellActions, shellPage }) => {
    await shellActions.gotoDashboard();
    await expect(shellPage.page).toHaveURL(/.*\/admin\/dashboard/);
    
    try {
      await shellPage.page.waitForLoadState('networkidle', { timeout: 8000 });
    } catch {
      expect.fail('Page did not load in expected time');
    }

    const usersCard = shellPage.page.locator('text=Users');
    await expect(usersCard.first()).toBeVisible({ timeout: 8000 });
    expect(await usersCard.count()).toBeGreaterThan(0, "'Users' card should be displayed on the Overview page.");
  });
});
